// build.gradle: implementation "io.micrometer:micrometer-registry-prometheus"
@Service
public class OrderService {
    private final Counter orderCounter;
    private final Timer orderTimer;

    public OrderService(MeterRegistry registry) {
        this.orderCounter = Counter.builder("orders_created_total")
            .description("Total pesanan yang dibuat")
            .tag("channel", "web")
            .register(registry);
        this.orderTimer = Timer.builder("order_processing_seconds")
            .publishPercentileHistogram()
            .register(registry);
    }

    public void createOrder(Order order) {
        orderTimer.record(() -> {
            // Logika bisnis proses simpan pesanan
            orderCounter.increment();
        });
    }
}

import (
    "net/http"
    "github.com/prometheus/client_golang/prometheus"
    "github.com/prometheus/client_golang/prometheus/promauto"
    "github.com/prometheus/client_golang/prometheus/promhttp"
)
var (
    ordersCreated = promauto.NewCounter(prometheus.CounterOpts{
        Name: "orders_created_total",
        Help: "Total pesanan yang dibuat",
    })
    orderDuration = promauto.NewHistogram(prometheus.HistogramOpts{
        Name:    "order_processing_seconds",
        Help:    "Durasi pemrosesan pesanan",
        Buckets: prometheus.DefBuckets,
    })
)
func createOrder(w http.ResponseWriter, r *http.Request) {
    timer := prometheus.NewTimer(orderDuration)
    defer timer.ObserveDuration()
    // Logika bisnis proses simpan pesanan
    ordersCreated.Inc()
    w.WriteHeader(http.StatusCreated)
}
func main() {
    http.HandleFunc("/orders", createOrder)
    http.Handle("/metrics", promhttp.Handler())
    http.ListenAndServe(":8080", nil)
}

