    .retryOnException(e -> e instanceof IOException)
    .build();
Retry retry = Retry.of("payment-service-retry", config);
Supplier<Receipt> call = Retry.decorateSupplier(retry, () -> paymentClient.charge(order));

func chargeWithRetry(ctx context.Context, order Order) (Receipt, error) {
    backoff := 200 * time.Millisecond
    for attempt := 0; attempt < 3; attempt++ {
        cctx, cancel := context.WithTimeout(ctx, 2*time.Second) // Timeout per call
        receipt, err := paymentClient.Charge(cctx, order)
        cancel()
        if err == nil { return receipt, nil }

        // Tambahkan Jitter (acak) untuk mencegah konvoi retry simultan
        jitter := time.Duration(rand.Int63n(int64(backoff / 2)))
        time.Sleep(backoff + jitter)
        backoff *= 2
    }
    return Receipt{}, errors.New("gagal setelah 3 percobaan")
}

