import http from 'k6/http';
import { check, sleep } from 'k6';

export const options = {
    stages: [
        { duration: '1m', target: 100 }, // Naikkan load ke 100 virtual user
        { duration: '3m', target: 100 }, // Tahan konstan
        { duration: '1m', target: 0 },   // Ramp-down ke nol
    ],
    thresholds: {
        http_req_duration: ['p(95)<300'], // 95% request wajib di bawah 300ms (SLO)
        http_req_failed: ['rate<0.01'],   // Kegagalan request harus < 1%
    },
};

